package com.mmpantry.app;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatDelegate;
public class SettingsActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(30,30,30,20);l.setBackgroundColor(Ui.background(this));TextView h=Ui.text(this,"Settings",30);l.addView(h);TextView a=Ui.text(this,"Appearance",18);l.addView(a);Switch s=new Switch(this);s.setText("Dark mode");s.setTextColor(Ui.primary(this));s.setChecked(getSharedPreferences("mm_settings",0).getBoolean("dark",false));s.setOnCheckedChangeListener((v,on)->{getSharedPreferences("mm_settings",0).edit().putBoolean("dark",on).apply();AppCompatDelegate.setDefaultNightMode(on?AppCompatDelegate.MODE_NIGHT_YES:AppCompatDelegate.MODE_NIGHT_NO);});l.addView(s);TextView f=Ui.text(this,"\nMM Pantry\nMade with love from your pantry.\n\nYour pantry, your recipes, less waste.",16);f.setTextColor(Ui.secondary(this));l.addView(f);l.addView(NavBar.build(this,"settings"));setContentView(l);}}